const menu=document.querySelector('.menu-btn');const nav=document.querySelector('.nav-links');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});
const form=document.querySelector('#move-form');let plan='';form?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);plan=`搬家需求清单\n公司：${form.dataset.company}\n咨询电话：${form.dataset.phone}\n搬出区域：${d.get('from')}\n搬入区域：${d.get('to')}\n计划日期：${d.get('date')||'待商议'}\n搬运类型：${d.get('type')}\n楼层 / 电梯：${d.get('floor')}\n物品与补充事项：${d.get('items')||'电话沟通'}\n\n需进一步确认：车辆与人员、楼层及距离费用、拆装打包范围、停车与物业安排、报价有效期。\n本清单未发送给公司，不代表预约成功。`;document.querySelector('#plan-text').textContent=plan;document.querySelector('#plan-result').hidden=false;document.querySelector('#plan-result').scrollIntoView({behavior:'smooth',block:'center'})});document.querySelector('#download-plan')?.addEventListener('click',()=>{const blob=new Blob([plan],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='搬家需求清单.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});const date=document.querySelector('input[type=date]');if(date){const d=new Date();date.min=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
